import React from 'react';
import { NudgeProps as LDNudgeProps } from '@walmart-web/livingdesign-components';
export interface NudgeProps extends LDNudgeProps {
}
/**
 * The Nudge component is used to remind or provide instructions for the next-step in a process.
 * The information they provide should not be required for a user to complete a task.
 *
 *
 * ### Content
 *
 * #### Title
 *
 * Set the title for the LuminateNudge with the `title` prop:
 *
 * ```tsx
 * <Nudge title="Title">Content</Nudge>
 * ```
 *
 * #### Leading
 *
 * The Nudge accepts optional leading content through the `leading` prop:
 *
 * ```tsx
 * <Nudge
 *   leading={<LeadingIcon />}
 *   title="Title"
 * >
 *   Content
 * </Nudge>
 * ```
 *
 * #### Actions
 *
 * The Nudge accepts a group of one or more button-like components through the optional `actions` prop:
 *
 * ```tsx
 * <Nudge
 *   actions={
 *     <ButtonGroup>
 *       <Button>Action1</Button>
 *       <Button>Action2</Button>
 *     </ButtonGroup>
 *   }
 *   title="Title"
 * >
 *   Content
 * </Nudge>
 * ```
 *
 * ### Opening and closing
 *
 * The LuminateNudge has a close button. Add a callback handler function using the `onClose` prop:
 *
 * ```tsx
 * <Nudge
 *   onClose={(event) => console.log(event)}
 *   title="Title"
 * >
 *   Content
 * </Nudge>
 * ```
 */
export declare const Nudge: React.FC<NudgeProps>;
export declare const LuminateNudge: React.FC<NudgeProps>;
